SELECT 
FROM privacy_request
WHERE id = #{id} AND requester_user_id = #{requesterUserId}

SELECT 
FROM privacy_request
WHERE requester_user_id = #{requesterUserId}
ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT  FROM privacy_request

    WHERE status = #{status}

ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM privacy_request
WHERE requester_user_id = #{requesterUserId}
  AND request_type = 'WITHDRAW_CONSENT'
  AND consent_type = #{consentType}
  AND status IN ('OPEN', 'PROCESSING')
